INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c155855b-95d5-4fb8-9cd7-68739b6b56f2', 'c1c2c3d4-3030-4000-8000-000000000030', 16, 'Escolhas', 'Semana 3 — Reconstruir', '{"pch": "Toda manh\u00e3 voc\u00ea escolhe\u2026 mesmo quando acha que n\u00e3o.", "verse": "Dt 30,19", "lectio": "Deus coloca vida e morte diante de n\u00f3s. O que voc\u00ea escolhe hoje?", "practice": "Tome uma micro-decis\u00e3o que voc\u00ea adia h\u00e1 dias.", "question": "Qual escolha voc\u00ea tem evitado?"}'), ('022cabd4-752c-4df8-8e91-9e8fe44cdca1', 'c1c2c3d4-3030-4000-8000-000000000030', 17, 'Hábitos', 'Semana 3 — Reconstruir', '{"pch": "Disciplina n\u00e3o \u00e9 castigo\u2026 \u00e9 cuidado com quem voc\u00ea est\u00e1 se tornando.", "verse": "1Cor 9,27", "lectio": "Paulo disciplina o corpo. Qual \u00e1rea da sua vida precisa de ordem?", "practice": "Defina um micro-h\u00e1bito para os pr\u00f3ximos 7 dias.", "question": "Qual h\u00e1bito te aproxima de quem voc\u00ea quer ser?"}'), ('d9150e85-aa75-4b79-8feb-ceeeb96760a3', 'c1c2c3d4-3030-4000-8000-000000000030', 18, 'Disciplina', 'Semana 3 — Reconstruir', '{"pch": "O que d\u00f3i agora\u2026 forma depois.", "verse": "Hb 12,11", "lectio": "A disciplina parece dolorosa, mas gera fruto. Qual fruto voc\u00ea busca?", "practice": "Pratique algo dif\u00edcil por 15 minutos hoje, conscientemente.", "question": "Qual disciplina voc\u00ea resiste mas sabe que precisa?"}'), ('459230b6-a949-4e59-96cd-1e04dfdb96c3', 'c1c2c3d4-3030-4000-8000-000000000030', 19, 'Foco', 'Semana 3 — Reconstruir', '{"pch": "Foco n\u00e3o \u00e9 ignorar o resto\u2026 \u00e9 saber o que importa agora.", "verse": "Fl 3,13-14", "lectio": "Paulo avan\u00e7a para o alvo. Qual \u00e9 o seu alvo neste momento?", "practice": "Elimine uma distra\u00e7\u00e3o por 24 horas.", "question": "O que merece sua aten\u00e7\u00e3o total hoje?"}'), ('7b5634a6-a6a0-43c7-8919-77729705818a', 'c1c2c3d4-3030-4000-8000-000000000030', 20, 'Constância', 'Semana 3 — Reconstruir', '{"pch": "Desistir \u00e9 f\u00e1cil\u2026 mas o fruto vem pra quem fica.", "verse": "Gl 6,9", "lectio": "N\u00e3o se canse de fazer o bem. Em que \u00e1rea voc\u00ea cansa r\u00e1pido?", "practice": "Recomece algo que voc\u00ea abandonou esta semana.", "question": "Onde voc\u00ea tem desistido cedo demais?"}'), ('4281821b-5b55-4965-b5c5-4c01130eec6a', 'c1c2c3d4-3030-4000-8000-000000000030', 21, 'Identidade', 'Semana 3 — Reconstruir', '{"pch": "Voc\u00ea n\u00e3o \u00e9 o que fez\u2026 \u00e9 o que foi feito para ser.", "verse": "Ef 2,10", "lectio": "Somos obra de Deus. O que isso muda na forma como voc\u00ea se v\u00ea?", "practice": "Escreva: quem eu sou, sem t\u00edtulos, sem pap\u00e9is, sem m\u00e1scaras.", "question": "Quem voc\u00ea \u00e9 quando ningu\u00e9m est\u00e1 olhando?"}'), ('5dd229da-b343-49b7-9c7a-f79db3faf550', 'c1c2c3d4-3030-4000-8000-000000000030', 22, 'Presença', 'Semana 4 — Integrar', '{"pch": "Deus n\u00e3o est\u00e1 no destino\u2026 est\u00e1 no caminho.", "verse": "Sl 139,7-10", "lectio": "Leia e pergunte: em que momento do meu dia Deus esteve mais perto?", "practice": "Viva uma hora inteira com aten\u00e7\u00e3o plena ao presente.", "question": "Onde voc\u00ea sente a presen\u00e7a de Deus hoje?"}'), ('e1445250-0515-4257-8395-5e40727cc79b', 'c1c2c3d4-3030-4000-8000-000000000030', 23, 'Propósito', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o precisa inventar um prop\u00f3sito\u2026 precisa descobrir o que j\u00e1 foi plantado.", "verse": "Jr 29,11", "lectio": "Deus tem planos de paz. O que ressoa dentro de voc\u00ea ao ler isso?", "practice": "Liste 3 coisas que te d\u00e3o energia e alegria verdadeira.", "question": "O que te faz sentir vivo?"}'), ('d58e1b64-b4b6-4bd7-ae8a-9175a9b03814', 'c1c2c3d4-3030-4000-8000-000000000030', 24, 'Confiança', 'Semana 4 — Integrar', '{"pch": "Confiar n\u00e3o \u00e9 entender\u2026 \u00e9 caminhar mesmo sem ver.", "verse": "Sl 37,5", "lectio": "Entregue o seu caminho ao Senhor. O que voc\u00ea ainda segura?", "practice": "Entregue uma preocupa\u00e7\u00e3o em ora\u00e7\u00e3o e n\u00e3o a retome hoje.", "question": "Em que \u00e1rea da vida voc\u00ea precisa confiar mais?"}'), ('0363689a-20b6-44e4-ab42-70ef3e29a688', 'c1c2c3d4-3030-4000-8000-000000000030', 25, 'Entrega', 'Semana 4 — Integrar', '{"pch": "A maior liberdade\u2026 \u00e9 querer o que Deus quer.", "verse": "Lc 22,42", "lectio": "Jesus no Gets\u00eamani: n\u00e3o a minha, mas a Tua vontade. O que isso significa pra voc\u00ea?", "practice": "Fa\u00e7a uma ora\u00e7\u00e3o de entrega: escreva o que voc\u00ea entrega hoje.", "question": "O que voc\u00ea ainda n\u00e3o entregou?"}'), ('3f5434e3-ec6b-44b7-870b-47004ab1632f', 'c1c2c3d4-3030-4000-8000-000000000030', 26, 'Paz', 'Semana 4 — Integrar', '{"pch": "A paz de Cristo n\u00e3o \u00e9 aus\u00eancia de luta\u2026 \u00e9 presen\u00e7a em meio a ela.", "verse": "Jo 14,27", "lectio": "Leia e pergunte: a paz que eu busco \u00e9 do mundo ou de Deus?", "practice": "Identifique uma fonte de agita\u00e7\u00e3o e entregue-a em sil\u00eancio.", "question": "O que rouba sua paz?"}'), ('e576064d-c53e-44c8-8997-eb90d6527d84', 'c1c2c3d4-3030-4000-8000-000000000030', 27, 'Direção', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o precisa ver todo o caminho\u2026 s\u00f3 o pr\u00f3ximo passo.", "verse": "Sl 119,105", "lectio": "A Palavra \u00e9 l\u00e2mpada. Que luz ela traz para sua decis\u00e3o de hoje?", "practice": "Tome uma decis\u00e3o que voc\u00ea adia, confiando na luz que j\u00e1 tem.", "question": "Qual \u00e9 o pr\u00f3ximo passo que voc\u00ea j\u00e1 sabe?"}'), ('a0445828-d326-4697-9786-60b513aaba02', 'c1c2c3d4-3030-4000-8000-000000000030', 28, 'Compromisso', 'Semana 4 — Integrar', '{"pch": "Decidir \u00e9 cortar todas as outras op\u00e7\u00f5es\u2026 e caminhar.", "verse": "Js 24,15", "lectio": "Josu\u00e9 escolhe servir ao Senhor. Qual \u00e9 a sua escolha hoje?", "practice": "Escreva um compromisso concreto para os pr\u00f3ximos 30 dias.", "question": "Com o que voc\u00ea se compromete a partir de agora?"}'), ('013d164a-ae98-43c4-9957-2211f898021e', 'c1c2c3d4-3030-4000-8000-000000000030', 29, 'Consolidação', 'Semana 4 — Integrar', '{"pch": "Ouvir sem fazer\u2026 \u00e9 o sono da alma.", "verse": "Tg 1,22-25", "lectio": "Seja praticante da Palavra. Qual ensinamento desta jornada precisa virar a\u00e7\u00e3o?", "practice": "Releia suas reflex\u00f5es da semana 1. O que mudou?", "question": "O que voc\u00ea aprendeu mas ainda n\u00e3o praticou?"}'), ('5529aca4-697e-4176-af9d-096c5a60c73f', 'c1c2c3d4-3030-4000-8000-000000000030', 30, 'Novo Começo', 'Semana 4 — Integrar', '{"pch": "Voc\u00ea n\u00e3o chegou ao fim\u2026 voc\u00ea saiu de onde estava.", "verse": "Ap 21,5", "lectio": "Eu fa\u00e7o novas todas as coisas. O que \u00e9 novo em voc\u00ea agora?", "practice": "Escreva uma carta para si mesmo: quem eu era no dia 1, quem eu sou no dia 30, e para onde vou.", "question": "Quem voc\u00ea se tornou?"}'), ('2711a145-076a-4092-99b4-9a1f1992ae2b', 'c3c3c3c3-3030-4000-8000-000000000003', 1, 'Dia 1 — Ruído', 'Semana 1: Parar', '{"pch": "Depois do fogo\u2026 uma voz mansa e suave. Deus n\u00e3o grita. Ele sussurra. Mas voc\u00ea precisa parar para ouvir.", "verse": "1Rs 19,12", "lectio": "Leia 1Rs 19,9-13. Elias no monte.", "practice": "Liste tudo que est\u00e1 na sua cabe\u00e7a agora. Tudo. Sem filtro.", "question": "Que ru\u00eddo constante ocupa sua mente?"}'), ('61ed9a2c-de4a-446e-bda9-c8902adbe470', 'c3c3c3c3-3030-4000-8000-000000000003', 2, 'Dia 2 — Overload', 'Semana 1: Parar', '{"pch": "Acalmei e sosseguei a minha alma\u2026 como uma crian\u00e7a no colo da m\u00e3e. Menos \u00e9 mais.", "verse": "Sl 131,1-2", "lectio": "Leia Sl 131. O salmo mais curto e mais profundo.", "practice": "Elimine 1 compromisso desnecess\u00e1rio esta semana.", "question": "O que te sobrecarrega mais: o que acontece ou o que voc\u00ea pensa sobre o que acontece?"}'), ('512f28b3-a771-4f78-8330-a88f58f6d656', 'c3c3c3c3-3030-4000-8000-000000000003', 3, 'Dia 3 — Ansiedade', 'Semana 1: Parar', '{"pch": "Basta a cada dia o seu pr\u00f3prio mal\u2026 Pensar no amanh\u00e3 \u00e9 roubar a paz de hoje.", "verse": "Mt 6,34", "lectio": "Leia Mt 6,25-34. Olhai os l\u00edrios do campo.", "practice": "Anote 3 preocupa\u00e7\u00f5es. Ao lado de cada uma, escreva: posso controlar isso? Sim ou n\u00e3o.", "question": "Sobre o que voc\u00ea se preocupa que n\u00e3o pode controlar?"}'), ('a7f8dab1-f5f2-4cd5-aed2-6bd4d8588f66', 'c3c3c3c3-3030-4000-8000-000000000003', 4, 'Dia 4 — Respirar', 'Semana 1: Parar', '{"pch": "Soprou nas suas narinas o f\u00f4lego de vida\u2026 A respira\u00e7\u00e3o \u00e9 o primeiro presente de Deus.", "verse": "Gn 2,7", "lectio": "Leia Gn 2,4-7. Deus formou e soprou.", "practice": "Pratique 5 minutos de respira\u00e7\u00e3o consciente: 4s inspira, 7s segura, 8s expira.", "question": "Quando foi a \u00faltima vez que voc\u00ea respirou com consci\u00eancia?"}'), ('2988c988-44af-4744-bbf5-031bcccf7926', 'c3c3c3c3-3030-4000-8000-000000000003', 5, 'Dia 5 — Pensamentos', 'Semana 1: Parar', '{"pch": "Pensai em tudo o que \u00e9 verdadeiro, nobre, justo\u2026 Voc\u00ea \u00e9 o que pensa repetidamente.", "verse": "Fl 4,8", "lectio": "Leia Fl 4,4-9. A receita da paz.", "practice": "Observe seus pensamentos por 10 min sem reagir. Apenas note.", "question": "Quais pensamentos se repetem na sua mente?"}'), ('b4a145ff-c7e3-4083-bb66-921abf7f0735', 'c3c3c3c3-3030-4000-8000-000000000003', 6, 'Dia 6 — Digital', 'Semana 1: Parar', '{"pch": "O olho n\u00e3o se farta de ver\u2026 nem o ouvido de ouvir. O scroll infinito \u00e9 a torre de Babel moderna.", "verse": "Ec 1,8", "lectio": "Leia Ec 1,1-11. Vaidade das vaidades.", "practice": "Fique 2 horas sem celular. Observe o que acontece dentro de voc\u00ea.", "question": "Quanto tempo por dia sua mente \u00e9 alimentada por telas?"}'), ('cc39322a-514a-4e0e-bc2d-ce1ab1c1eb2d', 'c3c3c3c3-3030-4000-8000-000000000003', 7, 'Dia 7 — Sabbath mental', 'Semana 1: Parar', '{"pch": "Lembra-te do dia de s\u00e1bado para o santificar\u2026 Sua mente tamb\u00e9m precisa de descanso sagrado.", "verse": "Ex 20,8", "lectio": "Leia Ex 20,8-11. O mandamento do descanso.", "practice": "Crie um mini-sabbath: 3 horas sem produtividade, s\u00f3 presen\u00e7a.", "question": "Quando foi a \u00faltima vez que sua mente descansou de verdade?"}'), ('df69c5d1-aa43-4247-a7b5-9ecfd1c5a72b', 'c3c3c3c3-3030-4000-8000-000000000003', 8, 'Dia 8 — Prioridades', 'Semana 2: Organizar', '{"pch": "Maria escolheu a melhor parte\u2026 Nem tudo que \u00e9 urgente \u00e9 importante.", "verse": "Lc 10,42", "lectio": "Leia Lc 10,38-42. Marta e Maria.", "practice": "Liste suas 5 prioridades. Compare com como gasta seu tempo.", "question": "O que \u00e9 realmente importante na sua vida agora?"}'), ('004afa2a-d390-4faa-bbbb-770dff01f616', 'c3c3c3c3-3030-4000-8000-000000000003', 9, 'Dia 9 — Simplicidade', 'Semana 2: Organizar', '{"pch": "Se n\u00e3o vos converterdes como crian\u00e7as\u2026 A crian\u00e7a n\u00e3o complica. Ela vive.", "verse": "Mt 18,3", "lectio": "Leia Mt 18,1-5. Tornar-se como crian\u00e7a.", "practice": "Simplifique 1 \u00e1rea da sua vida hoje. Menos \u00e9 clareza.", "question": "O que voc\u00ea est\u00e1 complicando desnecessariamente?"}'), ('6e35250f-3494-46c4-8a9e-16fd80ebbf64', 'c3c3c3c3-3030-4000-8000-000000000003', 10, 'Dia 10 — Foco', 'Semana 2: Organizar', '{"pch": "Olhando para Jesus\u2026 autor e consumador da f\u00e9. Foco \u00e9 decidir para onde olhar.", "verse": "Hb 12,2", "lectio": "Leia Hb 12,1-3. Correr com perseveran\u00e7a.", "practice": "Escolha 1 coisa importante. Dedique 1 hora ininterrupta a ela.", "question": "No que voc\u00ea deveria estar focado mas n\u00e3o est\u00e1?"}'), ('6de31ec2-ad63-42ce-8a40-c843f91b4eaa', 'c3c3c3c3-3030-4000-8000-000000000003', 11, 'Dia 11 — Decisões', 'Semana 2: Organizar', '{"pch": "Se algu\u00e9m tem falta de sabedoria, pe\u00e7a a Deus\u2026 Clareza vem de quem v\u00ea tudo.", "verse": "Tg 1,5", "lectio": "Leia Tg 1,2-8. Pedir com f\u00e9, sem duvidar.", "practice": "Ore especificamente sobre uma decis\u00e3o. Depois, escreva o que sentiu.", "question": "Que decis\u00e3o te paralisa por falta de clareza?"}'), ('09fbf4de-26cd-4257-ad1f-04d5c75458f6', 'c3c3c3c3-3030-4000-8000-000000000003', 12, 'Dia 12 — Mente renovada', 'Semana 2: Organizar', '{"pch": "Transformai-vos pela renova\u00e7\u00e3o da mente\u2026 Pensar diferente \u00e9 o come\u00e7o de viver diferente.", "verse": "Rm 12,2", "lectio": "Leia Rm 12,1-2. Culto racional.", "practice": "Identifique 1 pensamento negativo recorrente. Substitua por uma verdade b\u00edblica.", "question": "Que padr\u00e3o de pensamento precisa mudar?"}'), ('f27b563c-6f42-42ae-9c21-029b44359198', 'c3c3c3c3-3030-4000-8000-000000000003', 13, 'Dia 13 — Verdade', 'Semana 2: Organizar', '{"pch": "Conhecereis a verdade e a verdade vos libertar\u00e1\u2026 Mentiras internas aprisionam. A verdade liberta.", "verse": "Jo 8,32", "lectio": "Leia Jo 8,31-36. A liberdade real.", "practice": "Escreva a mentira. Ao lado, escreva a verdade de Deus sobre voc\u00ea.", "question": "Que mentira sobre si mesmo voc\u00ea acreditou por tempo demais?"}'), ('576dc901-367c-491c-88a5-7633757d1521', 'c3c3c3c3-3030-4000-8000-000000000003', 14, 'Dia 14 — Silêncio', 'Semana 2: Organizar', '{"pch": "Aquietai-vos\u2026 No sil\u00eancio, os pensamentos se acomodam como sedimento na \u00e1gua.", "verse": "Sl 46,10", "lectio": "Leia Sl 46. Deus \u00e9 ref\u00fagio.", "practice": "15 minutos de sil\u00eancio contemplativo. Sem guia, sem m\u00fasica.", "question": "O que aparece quando tudo fica em sil\u00eancio?"}'), ('51f9a773-6c24-4386-adc1-05b27c4bc477', 'c3c3c3c3-3030-4000-8000-000000000003', 15, 'Dia 15 — Sabedoria', 'Semana 3: Discernir', '{"pch": "O princ\u00edpio da sabedoria \u00e9: adquire sabedoria\u2026 A sabedoria n\u00e3o \u00e9 informa\u00e7\u00e3o \u2014 \u00e9 discernimento.", "verse": "Pv 4,7", "lectio": "Leia Pv 4,1-9. A sabedoria como tesouro.", "practice": "Pe\u00e7a conselho a algu\u00e9m mais velho e s\u00e1bio sobre algo que te inquieta.", "question": "Qual a diferen\u00e7a entre saber e ser s\u00e1bio na sua vida?"}'), ('183e992f-ce19-4f65-980d-897b462aa522', 'c3c3c3c3-3030-4000-8000-000000000003', 16, 'Dia 16 — Discernimento', 'Semana 3: Discernir', '{"pch": "Provai os esp\u00edritos\u2026 Nem todo pensamento que surge \u00e9 verdadeiro. Discernir \u00e9 separar.", "verse": "1Jo 4,1", "lectio": "Leia 1Jo 4,1-6. O esp\u00edrito da verdade.", "practice": "Hoje, antes de agir por impulso, pergunte: isso vem da paz ou da ansiedade?", "question": "Como voc\u00ea distingue um pensamento \u00fatil de um destrutivo?"}'), ('39521ae4-ffb9-43ae-b257-192f8330ce80', 'c3c3c3c3-3030-4000-8000-000000000003', 17, 'Dia 17 — Intuição', 'Semana 3: Discernir', '{"pch": "O Esp\u00edrito da verdade vos guiar\u00e1\u2026 Intui\u00e7\u00e3o espiritual \u00e9 o GPS divino.", "verse": "Jo 16,13", "lectio": "Leia Jo 16,12-15. O Esp\u00edrito ensina.", "practice": "Tome uma decis\u00e3o pequena hoje usando apenas intui\u00e7\u00e3o e ora\u00e7\u00e3o.", "question": "Quando sua intui\u00e7\u00e3o te guiou corretamente?"}'), ('3c5ad66f-3af6-43a7-a225-7aa6f232da86', 'c3c3c3c3-3030-4000-8000-000000000003', 18, 'Dia 18 — Paciência', 'Semana 3: Discernir', '{"pch": "A perseveran\u00e7a tenha obra perfeita\u2026 Clareza raramente \u00e9 instant\u00e2nea. \u00c0s vezes, esperar \u00e9 a resposta.", "verse": "Tg 1,4", "lectio": "Leia Tg 1,2-4. Alegria nas prova\u00e7\u00f5es.", "practice": "Espere antes de responder algo hoje. Observe o que muda.", "question": "Em que \u00e1rea da vida voc\u00ea precisa de mais paci\u00eancia?"}'), ('58587bc7-c34a-4cff-834a-6abdb165c3ad', 'c3c3c3c3-3030-4000-8000-000000000003', 19, 'Dia 19 — Perspectiva', 'Semana 3: Discernir', '{"pch": "Os meus pensamentos n\u00e3o s\u00e3o os vossos pensamentos\u2026 \u00c0s vezes, clareza \u00e9 aceitar que voc\u00ea n\u00e3o v\u00ea tudo.", "verse": "Is 55,8-9", "lectio": "Leia Is 55,6-11. A palavra que n\u00e3o volta vazia.", "practice": "Escreva sua situa\u00e7\u00e3o atual como se fosse Deus descrevendo-a para voc\u00ea.", "question": "O que mudaria se voc\u00ea visse sua situa\u00e7\u00e3o do ponto de vista de Deus?"}'), ('7dc18a7c-f96b-41c1-8ac6-60b3db7444e4', 'c3c3c3c3-3030-4000-8000-000000000003', 20, 'Dia 20 — Soltar', 'Semana 3: Discernir', '{"pch": "Lan\u00e7a sobre o Senhor o teu fardo\u2026 Pensamentos obsessivos s\u00e3o fardos que n\u00e3o te pertencem.", "verse": "Sl 55,22", "lectio": "Leia Sl 55,16-23. Deus sustenta.", "practice": "Escreva o pensamento que te atormenta num papel. Depois, rasgue-o como ato simb\u00f3lico.", "question": "Que pensamento voc\u00ea precisa parar de carregar?"}'), ('a80a6282-9cba-41df-99a0-7c50d3cc0798', 'c3c3c3c3-3030-4000-8000-000000000003', 21, 'Dia 21 — Ordem interior', 'Semana 3: Discernir', '{"pch": "Deus n\u00e3o \u00e9 de confus\u00e3o, mas de paz\u2026 A ordem interior reflete a ordem divina.", "verse": "1Cor 14,33", "lectio": "Leia 1Cor 14,26-33. Ordem no culto.", "practice": "Organize algo externo (mesa, quarto, agenda) como reflexo da ordem interna que busca.", "question": "O que na sua vida interna est\u00e1 bagun\u00e7ado?"}'), ('68bfdebc-e08e-4eca-b3a9-27d1160b6c90', 'c3c3c3c3-3030-4000-8000-000000000003', 22, 'Dia 22 — Atenção', 'Semana 4: Integrar', '{"pch": "Cuidado com o modo como voc\u00eas ouvem\u2026 Aten\u00e7\u00e3o \u00e9 a ora\u00e7\u00e3o mais b\u00e1sica.", "verse": "Lc 8,18", "lectio": "Leia Lc 8,16-18. A l\u00e2mpada e a aten\u00e7\u00e3o.", "practice": "Pratique aten\u00e7\u00e3o plena numa atividade simples: comer, caminhar, respirar.", "question": "No que voc\u00ea tem prestado aten\u00e7\u00e3o?"}'), ('ffed5b73-6714-4a5d-bcfd-649a6ad5a7dc', 'c3c3c3c3-3030-4000-8000-000000000003', 23, 'Dia 23 — Rotina', 'Semana 4: Integrar', '{"pch": "Daniel orava tr\u00eas vezes ao dia\u2026 Rotina sagrada cria espa\u00e7o para clareza.", "verse": "Dn 6,10", "lectio": "Leia Dn 6,6-13. A fidelidade de Daniel.", "practice": "Crie uma rotina matinal de 15 min: sil\u00eancio, leitura, ora\u00e7\u00e3o.", "question": "Como \u00e9 sua rotina matinal? Ela alimenta ou drena sua mente?"}'), ('f4e9174e-8067-45cb-97bd-56e0628f5b55', 'c3c3c3c3-3030-4000-8000-000000000003', 24, 'Dia 24 — Contentamento', 'Semana 4: Integrar', '{"pch": "Aprendi a estar contente em toda situa\u00e7\u00e3o\u2026 Contentamento n\u00e3o \u00e9 conformismo \u2014 \u00e9 liberdade.", "verse": "Fl 4,11", "lectio": "Leia Fl 4,10-13. O segredo de Paulo.", "practice": "Liste 10 coisas que j\u00e1 tem e que algu\u00e9m sonha em ter.", "question": "O que te falta para ser feliz? Ser\u00e1 que realmente falta?"}'), ('bcc2b146-9844-4222-b920-924ad03d7c3b', 'c3c3c3c3-3030-4000-8000-000000000003', 25, 'Dia 25 — Criatividade', 'Semana 4: Integrar', '{"pch": "No princ\u00edpio, Deus criou\u2026 Criatividade \u00e9 imagem de Deus em a\u00e7\u00e3o. Mentes claras criam.", "verse": "Gn 1,1", "lectio": "Leia Gn 1,1-5. O primeiro ato criativo.", "practice": "Crie algo hoje: um texto, um desenho, uma m\u00fasica, uma receita.", "question": "O que voc\u00ea criaria se tivesse clareza?"}'), ('41a9b8e8-9f49-47c6-a8b8-bd1084b4a01e', 'c3c3c3c3-3030-4000-8000-000000000003', 26, 'Dia 26 — Palavras', 'Semana 4: Integrar', '{"pch": "A morte e a vida est\u00e3o no poder da l\u00edngua\u2026 O que voc\u00ea diz molda o que voc\u00ea pensa.", "verse": "Pv 18,21", "lectio": "Leia Pv 18,20-21. O fruto da boca.", "practice": "Hoje, fale apenas o que edifica. Observe como isso muda seu estado mental.", "question": "Que palavras voc\u00ea repete sobre si mesmo?"}'), ('b90cea0d-39c9-41de-a0d0-39a1b35457af', 'c3c3c3c3-3030-4000-8000-000000000003', 27, 'Dia 27 — Direção', 'Semana 4: Integrar', '{"pch": "L\u00e2mpada para os meus p\u00e9s\u2026 A Palavra n\u00e3o ilumina o caminho todo \u2014 s\u00f3 o pr\u00f3ximo passo.", "verse": "Sl 119,105", "lectio": "Leia Sl 119,105-112. Luz suficiente.", "practice": "Defina 1 pr\u00f3ximo passo claro. N\u00e3o o segundo. S\u00f3 o primeiro.", "question": "Qual \u00e9 o pr\u00f3ximo passo que voc\u00ea precisa dar?"}'), ('7fded1c2-46aa-483e-a0c5-3b254ebf399f', 'c3c3c3c3-3030-4000-8000-000000000003', 28, 'Dia 28 — Confiança', 'Semana 4: Integrar', '{"pch": "Confia no Senhor\u2026 e n\u00e3o te estribes no teu pr\u00f3prio entendimento. Clareza final vem da rendi\u00e7\u00e3o.", "verse": "Pv 3,5-6", "lectio": "Leia Pv 3,1-8. O caminho da confian\u00e7a.", "practice": "Entregue uma decis\u00e3o a Deus hoje. Confie sem entender.", "question": "Em que \u00e1rea voc\u00ea tenta entender quando deveria confiar?"}'), ('6ac00f54-adf7-4709-8814-c82ec54c3c00', 'c3c3c3c3-3030-4000-8000-000000000003', 29, 'Dia 29 — Paz mental', 'Semana 4: Integrar', '{"pch": "A paz de Deus que excede todo entendimento\u2026 guardar\u00e1 vosso cora\u00e7\u00e3o e mente. Paz que a l\u00f3gica n\u00e3o explica.", "verse": "Fl 4,7", "lectio": "Leia Fl 4,6-7. Ora\u00e7\u00e3o que gera paz.", "practice": "Ore sobre cada preocupa\u00e7\u00e3o. Depois, agrade\u00e7a como se j\u00e1 tivesse a resposta.", "question": "O que significaria ter paz mental de verdade?"}'), ('245fdff3-766d-4c27-b4d3-acdfbf435181', 'c3c3c3c3-3030-4000-8000-000000000003', 30, 'Dia 30 — Mente clara', 'Semana 4: Integrar', '{"pch": "Deus nos deu esp\u00edrito de poder, amor e mente s\u00e3\u2026 Clareza mental n\u00e3o \u00e9 destino \u2014 \u00e9 pr\u00e1tica di\u00e1ria.", "verse": "2Tm 1,7", "lectio": "Leia 2Tm 1,6-12. Reavivar a chama.", "practice": "Releia todas as reflex\u00f5es. Escreva seu manifesto de clareza mental em 5 frases.", "question": "O que mudou na sua mente nesses 30 dias?"}'), ('6248ed3e-911f-46ee-ad1f-d94b08f19285', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 1, 'O olhar que se volta', NULL, '{"intro": "Psicologicamente, aceitar a exist\u00eancia de uma dor \u00e9 o in\u00edcio do fim do trauma.", "prayer": "Escreva sobre essa ferida sem filtros.", "practice": "Reserve 5 minutos para olhar honestamente para algo que lhe d\u00f3i.", "reflection": "A ferida s\u00f3 pode ser curada quando deixamos de escond\u00ea-la de n\u00f3s mesmos. O primeiro passo \u00e9 o reconhecimento.", "journal_prompt": "O que em voc\u00ea ainda tem medo de ser visto?"}'), ('7f70a32a-9138-415d-bd27-f56ce3062fe6', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 2, 'O perdão como libertação', NULL, '{"intro": "O ressentimento \u00e9 uma pris\u00e3o que voc\u00ea constr\u00f3i para o outro e acaba morando nela.", "prayer": "Em sil\u00eancio, pronuncie: Eu o libero, eu me libero.", "practice": "Identifique uma pessoa ou situa\u00e7\u00e3o que voc\u00ea ainda carrega.", "reflection": "Perdoar n\u00e3o \u00e9 esquecer, \u00e9 tirar o peso do passado dos seus ombros.", "journal_prompt": "Qual peso voc\u00ea est\u00e1 pronto para soltar?"}'), ('77eaa697-dc89-43bd-ab9f-361cc131577b', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 3, 'A voz que consola', NULL, '{"intro": "O trauma nos isola; a cura nos reconecta \u00e0 nossa pr\u00f3pria dignidade.", "prayer": "Fique em sil\u00eancio absoluto por 10 minutos.", "practice": "Respire fundo e imagine-se sendo abra\u00e7ado pelo amor que nunca falha.", "reflection": "A cura vem de uma voz que sussurra: voc\u00ea n\u00e3o est\u00e1 mais sozinho.", "journal_prompt": "Se o amor falasse com voc\u00ea hoje, o que diria?"}'), ('c4566c85-797e-499d-ae19-11db3cea8862', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 4, 'Desapego do passado', NULL, '{"intro": "Tentar viver no passado \u00e9 tentar preencher um vaso quebrado com areia.", "prayer": "Queime esse papel simbolicamente ou rasgue-o.", "practice": "Liste tr\u00eas coisas que te mant\u00eam preso ao que j\u00e1 passou.", "reflection": "O passado \u00e9 um espelho, n\u00e3o uma morada.", "journal_prompt": "Quem voc\u00ea seria se n\u00e3o carregasse esse passado?"}'), ('bb55db15-57da-46f0-bb9f-f8ae171b0372', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 5, 'A nova identidade', NULL, '{"intro": "A cura redefine sua narrativa pessoal.", "prayer": "Afirme essas qualidades em voz alta.", "practice": "Defina-se agora com tr\u00eas qualidades que n\u00e3o dependem da sua dor.", "reflection": "Voc\u00ea n\u00e3o \u00e9 o que te aconteceu, voc\u00ea \u00e9 o que voc\u00ea escolhe fazer com isso.", "journal_prompt": "Como \u00e9 a sua vida quando voc\u00ea aceita quem voc\u00ea realmente \u00e9?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;